
CREATE TABLE IF NOT EXISTS users(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username TEXT UNIQUE NOT NULL, password TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','operator','viewer')));
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, user_id INTEGER REFERENCES users(id), expires DOUBLE PRECISION NOT NULL);
CREATE TABLE IF NOT EXISTS items(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sku TEXT UNIQUE NOT NULL, name TEXT NOT NULL, model_class TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS locations(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS stock(item_id INTEGER REFERENCES items(id), location_id INTEGER REFERENCES locations(id), quantity INTEGER NOT NULL CHECK(quantity>=0), version INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(item_id,location_id));
CREATE TABLE IF NOT EXISTS scans(id TEXT PRIMARY KEY, user_id INTEGER REFERENCES users(id), location_id INTEGER REFERENCES locations(id), mode TEXT NOT NULL, detections TEXT NOT NULL, snapshot TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS adjustments(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, request_key TEXT UNIQUE NOT NULL, payload_hash TEXT NOT NULL, scan_id TEXT REFERENCES scans(id), item_id INTEGER REFERENCES items(id), location_id INTEGER REFERENCES locations(id), previous_quantity INTEGER NOT NULL, verified_quantity INTEGER NOT NULL, difference INTEGER NOT NULL, reason TEXT NOT NULL, user_id INTEGER REFERENCES users(id), created_at TEXT NOT NULL, UNIQUE(scan_id,item_id,location_id));
CREATE TABLE IF NOT EXISTS returns(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, request_key TEXT UNIQUE NOT NULL, payload_hash TEXT NOT NULL, item_id INTEGER REFERENCES items(id), location_id INTEGER REFERENCES locations(id), quantity INTEGER NOT NULL CHECK(quantity>0), reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending inspection', user_id INTEGER REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS return_events(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, return_id INTEGER REFERENCES returns(id), previous_status TEXT, new_status TEXT NOT NULL, user_id INTEGER REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS movements(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, item_id INTEGER REFERENCES items(id), location_id INTEGER REFERENCES locations(id), difference INTEGER NOT NULL, resulting_quantity INTEGER NOT NULL, source_type TEXT NOT NULL, source_id INTEGER NOT NULL, user_id INTEGER REFERENCES users(id), created_at TEXT NOT NULL, UNIQUE(source_type,source_id));
CREATE TABLE IF NOT EXISTS scan_commits(request_key TEXT PRIMARY KEY, payload_hash TEXT NOT NULL, scan_id TEXT UNIQUE REFERENCES scans(id), result TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS session_activity(token TEXT PRIMARY KEY REFERENCES sessions(token) ON DELETE CASCADE, last_seen DOUBLE PRECISION NOT NULL);
CREATE TABLE IF NOT EXISTS auth_attempts(bucket TEXT NOT NULL, attempted_at DOUBLE PRECISION NOT NULL);
CREATE INDEX IF NOT EXISTS auth_attempts_lookup ON auth_attempts(bucket,attempted_at);

